import { arrowGenerator } from "../../helpers";
import { StyleFn } from "..";

export const Tooltip: StyleFn = (theme, mode) => {
  const { color, elevation, font, opacity, size } = theme;
  const backgroundColor = color.surface.accent.overlay[mode];
  const borderColor = color.saturated.skyblue[mode];
  const { root: arrowRoot, arrow } = arrowGenerator(4, backgroundColor);

  return {
    root: {
      position: "absolute",
      zIndex: elevation.zindex.tooltip,
      fontSize: font.size.small,
      lineHeight: font.lineheight.small,
      backgroundColor,
      color: color.text.neutral.minimal[mode],
      padding: `${size.spacing[4]} ${size.spacing[8]}`,
      borderRadius: "3px",
      boxShadow: elevation.level1,
      opacity: opacity.tooltip,
      ...arrowRoot,
    },
    arrow,
    _large: {
      fontSize: font.size.medium,
      lineHeight: font.lineheight.medium,
      padding: `${size.spacing[8]} ${size.spacing[8]}`,
      "&[data-popper-placement^='top']": {
        borderTop: `4px solid ${borderColor}`,
      },
      "&[data-popper-placement^='bottom']": {
        borderBottom: `4px solid ${borderColor}`,
      },
      "&[data-popper-placement^='left']": {
        borderLeft: `4px solid ${borderColor}`,
      },
      "&[data-popper-placement^='right']": {
        borderRight: `4px solid ${borderColor}`,
      },
    },
    title: {
      fontWeight: font.weight.bold,
    },
  };
};
